import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`workflow-automation`,heroTitle:`Automate any workflow with agentic AI`,heroSubtitle:`Perplexity Computer builds multi-step agents, connects your tools, and executes complex workflows end to end — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Analyzing your workflow requirements and tool connections`,`Mapping multi-step tasks across your apps and data sources`,`Building agentic AI workflows with built-in error handling`,`Your automated workflow deployed and running — ready to scale`],generatingSteps:[`Identifying the tasks, triggers, and tools your workflow needs`,`Designing an agent to orchestrate each step across your stack`,`Configuring integrations, branching logic, and output formatting`,`Setting up monitoring so your workflow runs reliably on autopilot`],featureSectionTitle:`From idea to automated workflow`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can deploy`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Slack, Notion, Airtable, GitHub, Trello, Stripe — Computer wires into your tools and moves data between them without code.`,`Live automated workflows. Multi-step agent chains. Scheduled triggers and conditional logic. Formatted reports delivered to Slack or Google Sheets. Error alerts when something breaks.`],capabilitySectionTitle:`Your automation engineer, on autopilot`,capabilitySectionSubtitle:`Describe what you need, step away, get back a production-ready workflow.`,capabilityCards:[{title:`Multi-Step Agents`,description:`Computer can build agentic AI workflows that chain dozens of steps — reading data, making decisions, calling APIs, and writing outputs — far beyond what Zapier or n8n handle out of the box.`},{title:`Natural Language Setup`,description:`Computer can turn a plain-English description into a working automation — no drag-and-drop builders, no YAML configs like n8n AI or Gumloop require.`},{title:`Intelligent Branching`,description:`Computer can add conditional logic, error handling, and retry loops — building the kind of resilient agentic AI workflows that tools like Lindy AI and Manus AI promise but leave you to configure manually.`},{title:`Connect Your Tools`,description:`Computer can integrate Gmail, Google Sheets, Slack, Notion, Airtable, GitHub, and Stripe — build workflows across your entire stack without writing a line of code.`},{title:`Learns Your Patterns`,description:`Computer can remember your past workflows, preferred tools, and output formats — so every new automation builds on what already works, unlike starting from scratch in Genspark AI or Devin AI.`},{title:`Real-Time Monitoring`,description:`Computer can watch your running workflows around the clock — and alert you on Slack when a step fails, data looks wrong, or a connected service goes down.`}]});export{t as default};
